import java.util.*;

class Solution {
    public int ladderLength(String beginWord, String endWord, List<String> wordList) {
        Set<String> dictionary = new HashSet<>(wordList);
        if (!dictionary.contains(endWord)) {
            return 0;
        }

        Queue<String> queue = new ArrayDeque<>();
        queue.offer(beginWord);
        dictionary.remove(beginWord);
        int steps = 1;

        while (!queue.isEmpty()) {
            int size = queue.size();
            for (int levelIndex = 0; levelIndex < size; levelIndex++) {
                String word = queue.poll();
                char[] chars = word.toCharArray();
                for (int i = 0; i < chars.length; i++) {
                    char original = chars[i];
                    for (char letter = 'a'; letter <= 'z'; letter++) {
                        if (letter == original) {
                            continue;
                        }
                        chars[i] = letter;
                        String next = new String(chars);
                        if (next.equals(endWord)) {
                            return steps + 1;
                        }
                        if (dictionary.remove(next)) {
                            queue.offer(next);
                        }
                    }
                    chars[i] = original;
                }
            }
            steps++;
        }
        return 0;
    }
}

import java.util.*;

class Solution {
    public int ladderLength(String beginWord, String endWord, List<String> wordList) {
        Set<String> dictionary = new HashSet<>(wordList);
        if (!dictionary.contains(endWord)) {
            return 0;
        }

        Set<String> beginFrontier = new HashSet<>();
        Set<String> endFrontier = new HashSet<>();
        beginFrontier.add(beginWord);
        endFrontier.add(endWord);
        dictionary.remove(beginWord);
        dictionary.remove(endWord);
        int steps = 1;

        while (!beginFrontier.isEmpty() && !endFrontier.isEmpty()) {
            if (beginFrontier.size() > endFrontier.size()) {
                Set<String> temp = beginFrontier;
                beginFrontier = endFrontier;
                endFrontier = temp;
            }

            Set<String> nextFrontier = new HashSet<>();
            for (String word : beginFrontier) {
                char[] chars = word.toCharArray();
                for (int i = 0; i < chars.length; i++) {
                    char original = chars[i];
                    for (char letter = 'a'; letter <= 'z'; letter++) {
                        if (letter == original) {
                            continue;
                        }
                        chars[i] = letter;
                        String candidate = new String(chars);
                        if (endFrontier.contains(candidate)) {
                            return steps + 1;
                        }
                        if (dictionary.remove(candidate)) {
                            nextFrontier.add(candidate);
                        }
                    }
                    chars[i] = original;
                }
            }
            beginFrontier = nextFrontier;
            steps++;
        }
        return 0;
    }
}

import java.util.*;

class Solution {
    public int ladderLength(String beginWord, String endWord, List<String> wordList) {
        Set<String> dictionary = new HashSet<>(wordList);
        if (!dictionary.contains(endWord)) {
            return 0;
        }

        List<String> words = new ArrayList<>(wordList);
        if (!dictionary.contains(beginWord)) {
            words.add(beginWord);
        }

        Map<String, List<String>> patternMap = new HashMap<>();
        for (String word : words) {
            addPatterns(word, patternMap);
        }

        Queue<String> queue = new ArrayDeque<>();
        Set<String> visited = new HashSet<>();
        queue.offer(beginWord);
        visited.add(beginWord);
        int steps = 1;

        while (!queue.isEmpty()) {
            int size = queue.size();
            for (int levelIndex = 0; levelIndex < size; levelIndex++) {
                String word = queue.poll();
                for (int i = 0; i < word.length(); i++) {
                    String pattern = word.substring(0, i) + "*" + word.substring(i + 1);
                    List<String> bucket = patternMap.getOrDefault(pattern, Collections.emptyList());
                    for (String next : bucket) {
                        if (next.equals(endWord)) {
                            return steps + 1;
                        }
                        if (visited.add(next)) {
                            queue.offer(next);
                        }
                    }
                    bucket.clear();
                }
            }
            steps++;
        }
        return 0;
    }

    private void addPatterns(String word, Map<String, List<String>> patternMap) {
        for (int i = 0; i < word.length(); i++) {
            String pattern = word.substring(0, i) + "*" + word.substring(i + 1);
            patternMap.computeIfAbsent(pattern, key -> new ArrayList<>()).add(word);
        }
    }
}

import java.util.*;

class Solution {
    public int ladderLength(String beginWord, String endWord, List<String> wordList) {
        List<String> words = new ArrayList<>();
        words.add(beginWord);
        int target = -1;
        for (String word : wordList) {
            if (!word.equals(beginWord)) {
                if (word.equals(endWord)) {
                    target = words.size();
                }
                words.add(word);
            }
        }
        if (target == -1) {
            return 0;
        }

        List<List<Integer>> graph = new ArrayList<>();
        for (int i = 0; i < words.size(); i++) {
            graph.add(new ArrayList<>());
        }
        for (int i = 0; i < words.size(); i++) {
            for (int j = i + 1; j < words.size(); j++) {
                if (differsByOne(words.get(i), words.get(j))) {
                    graph.get(i).add(j);
                    graph.get(j).add(i);
                }
            }
        }

        int[] distance = new int[words.size()];
        Queue<Integer> queue = new ArrayDeque<>();
        queue.offer(0);
        distance[0] = 1;
        while (!queue.isEmpty()) {
            int node = queue.poll();
            if (node == target) {
                return distance[node];
            }
            for (int next : graph.get(node)) {
                if (distance[next] == 0) {
                    distance[next] = distance[node] + 1;
                    queue.offer(next);
                }
            }
        }
        return 0;
    }

    private boolean differsByOne(String a, String b) {
        int differences = 0;
        for (int i = 0; i < a.length(); i++) {
            if (a.charAt(i) != b.charAt(i)) {
                differences++;
                if (differences > 1) {
                    return false;
                }
            }
        }
        return differences == 1;
    }
}
